#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    int original = n;
    int reversed = 0;
    while (n > 0) {
        int digit = n % 10;
        reversed = reversed * 10 + digit;
        n /= 10;
    }
    cout << (reversed == original);
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int even;
    cin >> even;
    for (int j = 2; j < even; j++) {
        bool prime_a = true;
        if (j < 2) {
            prime_a = false;
        }
        for (int d = 2; d * d <= j; d++) {
            if (j % d == 0) {
                prime_a = false;
                break;
            }
        }

        int other = even - j;
        bool prime_b = true;
        if (other < 2) {
            prime_b = false;
        }
        for (int d = 2; d * d <= other; d++) {
            if (other % d == 0) {
                prime_b = false;
                break;
            }
        }

        if (prime_a && prime_b) {
            cout << j << ' ' << other;
            break;
        }
    }
    return 0;
}

